// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _minSum, uint256 _lockTime, uint256 _putAmount, uint256 _collectAmount) public {
        // Bound inputs to reasonable ranges
        vm.assume(_minSum > 0 && _minSum < 1e30);
        _lockTime = bound(_lockTime, 1, 1000000);
        _putAmount = bound(_putAmount, 0.001 ether, 1000 ether);
        _collectAmount = bound(_collectAmount, 0, _putAmount);

        // Initialize contract
        c.SetMinSum(_minSum);
        address log = address(0);
        c.SetLogFile(log);
        c.Initialized();

        // Record MinSum before any interactions
        uint256 minSumBefore = c.MinSum();

        // Fund the test contract and call Put
        address user = address(this);
        vm.deal(user, _putAmount);
        (bool successPut,) = address(c).call{value: _putAmount}(abi.encodeWithSignature("Put(uint256)", _lockTime));
        require(successPut, "Put failed");

        // Advance time so unlock condition passes
        vm.warp(block.timestamp + _lockTime + 1);

        // Call Collect
        (bool successCollect,) = address(c).call(abi.encodeWithSignature("Collect(uint256)", _collectAmount));

        // Rule: MinSum never changes after initialization
        assertTrue(c.MinSum() == minSumBefore);
    }
}

