import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint _val, uint _lockTime, uint _am, address _caller) public {
        // Bound inputs to reasonable ranges
        _val = bound(_val, 0, 1e18);
        _lockTime = bound(_lockTime, 0, 365 days);
        _am = bound(_am, 0, 1e18);
        vm.assume(_caller != address(0));

        // Initialize the contract
        c.SetMinSum(_val);
        c.Initialized();

        // Set up caller with some balance
        vm.deal(_caller, 1e18);
        vm.prank(_caller);
        c.Put{value: _am}(_lockTime);

        // Warp time to allow collection
        vm.warp(block.timestamp + _lockTime + 1);

        // Record MinSum before Collect
        uint minSumBefore = c.MinSum();

        // Call Collect (may revert, but we still observe MinSum after)
        vm.prank(_caller);
        (bool success,) = address(c).call(abi.encodeWithSignature("Collect(uint256)", _am));
        if (!success) {
            // If Collect reverts, MinSum should still be unchanged
            assertTrue(c.MinSum() == minSumBefore);
        } else {
            // If Collect succeeds, MinSum must still be unchanged
            assertTrue(c.MinSum() == minSumBefore);
        }
    }
}

