pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 minSumBeforeInit, uint256 minSumAfterInitFail, uint256 lockTime, uint256 collectAmount, uint256 depositAmount) public {
        // Bound inputs to reasonable ranges
        minSumBeforeInit = bound(minSumBeforeInit, 0, 1e30);
        minSumAfterInitFail = bound(minSumAfterInitFail, 0, 1e30);
        lockTime = bound(lockTime, 0, 1e9);
        collectAmount = bound(collectAmount, 0, 1e30);
        depositAmount = bound(depositAmount, 0, 1e30);

        // Step 1: Set MinSum before initialization
        if (minSumBeforeInit != 0) {
            c.SetMinSum(minSumBeforeInit);
        }

        // Step 2: Initialize the contract
        c.Initialized();

        // Step 3: Attempt to set MinSum again (should fail on reference, succeed on buggy version)
        // On reference C: revert, so state unchanged
        // On buggy M: return, so MinSum becomes minSumAfterInitFail
        c.SetMinSum(minSumAfterInitFail);

        // Step 4: Deposit funds to the caller (to enable Collect)
        vm.deal(address(this), depositAmount);
        c.Put{value: depositAmount}(lockTime);

        // Step 5: Warp time past unlockTime
        vm.warp(block.timestamp + lockTime + 1);

        // Step 6: Call Collect
        c.Collect(collectAmount);

        // General rule: After everything, MinSum() should equal minSumBeforeInit (the value set before init)
        // because the second SetMinSum should have reverted and not changed anything
        uint256 expectedMinSum = minSumBeforeInit;
        assertTrue(c.MinSum() == expectedMinSum);
    }
}

