// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 lockTime, uint256 amount, bool callSetLogFile, address logAddr) public {
        // Bound lockTime to avoid overflow
        lockTime = bound(lockTime, 0, 1e18);
        // Ensure initial balance
        vm.deal(address(this), 1 ether);
        // Optionally set the log address
        if (callSetLogFile) {
            c.SetLogFile(logAddr);
            // Ensure set afterwards
            vm.assume(c.LogFile() == logAddr);
        }
        // Put some ether
        c.Put{value: 1 ether}(lockTime);
        // Warp past unlock time
        vm.warp(block.timestamp + lockTime + 1);
        // Set minimum sum to 1 wei so we can collect
        c.SetMinSum(1);
        c.Initialized();
        // Now call Collect
        bool success;
        if (amount <= 1 ether) {
            // This should succeed if balance >= MinSum and >= amount and time > unlockTime
            (bool ok, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", amount));
            success = ok;
        } else {
            // amount > balance, will revert in the require or else
            (bool ok, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", amount));
            success = ok;
        }
        // The rule: if Collect succeeded, then LogFile must have been set (non-zero address)
        // Because the reference always sets LogFile before initialization, the mutant never does.
        // But the caller may have called SetLogFile, so we need to check: if success, then LogFile != address(0)?
        // Actually the rule: after success, LogFile must be the address set by SetLogFile, or if SetLogFile was called, it should be that address.
        // Simpler: if success, then the LogFile must be the address we set (or address(0) if we never set).
        // But the mutant never sets LogFile, so if we never called SetLogFile, LogFile is address(0) and success can happen -> break.
        // If we called SetLogFile, the mutant still doesn't set it -> address(0) -> fail.
        // So the general rule: success => LogFile != address(0) is always true for reference (since SetLogFile always sets it) and false for mutant.
        if (success) {
            assertTrue(c.LogFile() != address(0), "Collect succeeded but LogFile is zero");
        }
    }
}

