pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _am, uint256 _lockTime, uint256 _minSum) public {
        // Set minimum sum to a random value
        vm.assume(_minSum < type(uint256).max);
        c.SetMinSum(_minSum);
        // Initialize the contract
        c.Initialized();
        // Fund the contract with some ether to allow Collect to work
        vm.deal(address(c), 1 ether);
        // Have a random caller put some ether
        address payable sender = payable(address(0x1234));
        vm.deal(sender, 1 ether);
        vm.prank(sender);
        c.Put{value: 0.5 ether}(_lockTime);
        // Fast forward to unlock time
        vm.warp(block.timestamp + _lockTime + 1);
