        _am = bound(_am, 0, 0.1 ether);
        vm.prank(sender);
        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", _am));
        // After any Collect call, since SetLogFile was never called, LogFile must be address(0)
        assertTrue(address(c.LogFile()) == address(0));
    }
}

