pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 lockTime, uint256 putAmount, uint256 collectAmount) public {
        // Bound inputs to reasonable values (avoid overflow in reference)
        lockTime = bound(lockTime, 0, 100000);
        putAmount = bound(putAmount, 1, 1e18);
        collectAmount = bound(collectAmount, 1, putAmount);
        vm.assume(collectAmount > 0 && putAmount >= collectAmount);

        // Initialize the contract
        c.Initialized();

        // Set LogFile to some non-zero address (we need a contract that accepts Ether for Collect to succeed)
        // We can deploy a dummy contract or just use address(this) as a recipient
        vm.assume(caller != address(0));
        vm.deal(caller, putAmount);
        vm.prank(caller);
        c.Put{value: putAmount}(lockTime);

        // Record LogFile address before Collect
        address logBefore = address(c.Log());

        // Warp time past unlockTime
        vm.warp(block.timestamp + lockTime + 1);

        // Set MinSum to allow collect
        c.SetMinSum(collectAmount);

        // Call Collect
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmount));
        // Collect may revert if conditions not met (e.g., balance < MinSum or balance < _am)
        // We only care about the property when Collect succeeds, but we don't control whether it reverts.
        // The property should hold regardless: LogFile address never changes.

        // Assert the rule: LogFile address did not change
        assertTrue(address(c.Log()) == logBefore, "LogFile address changed");
    }
}

