    function testFuzz_property(uint256 _lockTime, uint256 _putAmount, uint256 _collectAmount, uint256 _minSum) public {
        // Bound inputs to avoid overflow/crash and to keep the ref satisfied
        _lockTime = bound(_lockTime, 0, 1000000);
        _putAmount = bound(_putAmount, 0, 1e24);
        _collectAmount = bound(_collectAmount, 0, 1e24);
        _minSum = bound(_minSum, 0, 1e24);

        // Setup
        c.SetMinSum(_minSum);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Fund caller and put
        vm.deal(address(this), _putAmount);
        c.Put{value: _putAmount}(_lockTime);

        uint256 oldBalance = address(this).balance;
        uint256 oldLogLen = c.Log().History(); // Actually History is a struct array, but we can't call length; skip

        // Warp past unlock
        vm.warp(block.timestamp + _lockTime + 1);

        // Call Collect
        bool reverted;
        try c.Collect(_collectAmount) { reverted = false; } catch { reverted = true; }

        // Rule: Collect should not succeed when _collectAmount > caller's balance
        // The caller's balance before Collect was c.Acc(address(this)).balance
        (uint256 unlockTime, uint256 callerBalance) = c.Acc(address(this));
        bool balanceAfter = (callerBalance >= _minSum && _collectAmount <= callerBalance) || reverted;
        // Simpler: if Collect succeeded then callerBalance >= _collectAmount must hold (since old balance decreased by exactly _collectAmount)
        // But after success, new balance = oldBalance - _collectAmount, so oldBalance - _collectAmount = callerBalance (assuming no other balance changes)
        // Actually we can't directly check oldBalance because it changes; we use the recorded balance after Put and before Collect
        // Better: if Collect did not revert, then c.Acc(address(this)).balance + _collectAmount == callerBalanceBefore (but we didn't record it)
        // Use the state variable: we know that before Collect, callerBalance was equal to c.Acc(address(this)).balance (which we can read before)
        // Let's record before
        (uint256 beforeUnlock, uint256 beforeBalance) = c.Acc(address(this));
        // Now call
        bool collectReverted;
        try c.Collect(_collectAmount) { collectReverted = false; } catch { collectReverted = true; }
        // After call
        (uint256 afterUnlock, uint256 afterBalance) = c.Acc(address(this));
        // Rule: if Collect did not revert, then _collectAmount <= beforeBalance
        if (!collectReverted) {
            assertTrue(_collectAmount <= beforeBalance, "Collect succeeded even though _collectAmount > balance");
        } else {
            // If it reverted, no constraint
            assertTrue(true);
        }
    }
}

