pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 minSum, uint256 balanceBefore, uint256 unlockTimeDelta, uint256 am) public {
        vm.assume(sender != address(0));
        vm.assume(balanceBefore >= 1);
        vm.assume(am > 0 && am <= balanceBefore);
        // Constrain so Collect will succeed: balance >= minSum, balance >= am, time > unlockTime
        uint256 _minSum = bound(minSum, 0, balanceBefore - am);
        vm.assume(block.timestamp > 0);
        uint256 _unlockTimeDelta = bound(unlockTimeDelta, 1, block.timestamp); // ensure unlockTime < now

        // Setup: initialize, set minSum, fund sender
        c.SetMinSum(_minSum);
        c.SetLogFile(address(0xdead));
        c.Initialized();
        vm.deal(sender, balanceBefore);
        vm.prank(sender);
        c.Put{value: balanceBefore}(0); // lockTime 0 => unlockTime = block.timestamp

        // Override unlockTime to be in the past
        // We need to access the internal mapping; instead, we rely on Put with a negative offset? Not possible.
        // Alternative: we can use the fact that Put sets unlockTime = block.timestamp + _lockTime.
        // Instead of trying to manipulate internal state, we just ensure we call at a time after lock expiration.
        // Since we set lockTime=0, unlockTime == block.timestamp + 0 == block.timestamp, which is not > block.timestamp.
        // To satisfy block.timestamp > unlockTime, we need lockTime=0 to make unlockTime = block.timestamp, which is not strictly greater.
        // So we must call Put with lockTime that results in unlockTime smaller than current block.timestamp.
        // The only way is to use a negative delta? No. So we must allow the case where block.timestamp > unlockTime after some time passes.
        // Since foundry fuzz block.timestamp is fixed per run, we cannot pass real time.
        // Instead, we can artificially set unlockTime to 0 by sending a call with lockTime that underflows? Not possible.
        // Hmm, let's think differently: we can make the Collect call fail by design, then check that no ether moves.
        // But the difference always shows when Collect succeeds. So we need a success path.
        // Workaround: we can use vm.warp to advance time after Put.
        // Let's do that:
        vm.prank(sender);
        c.Put{value: balanceBefore}(1); // lockTime = 1 => unlockTime = block.timestamp + 1
        vm.warp(block.timestamp + 2); // now time > unlockTime

        // Now call Collect
        uint256 senderBalanceBefore = sender.balance;
        uint256 contractBalanceBefore = address(c).balance;
        vm.prank(sender);
        (bool success, ) = address(c).call{gas: 100000}(abi.encodeWithSignature("Collect(uint256)", am));

        if (success) {
            uint256 senderBalanceAfter = sender.balance;
            uint256 contractBalanceAfter = address(c).balance;
            // The difference: in reference, value sent = am; in mutant, value sent = 0.
            // So reference: sender balance increases by am (net of gas? ignore gas by using call gas stipend)
            // Use low-level call with gas stipend 2300? The contract uses .call{value: _am} with all gas.
            // To be safe, we check contract balance decrease: in reference, contract loses am; in mutant, it loses 0.
            // But we don't know which version we have. So we check that contract balance decreased by exactly _am, 
            // which is true only in reference. In mutant, contract balance does not decrease (since value=0 sent), but balance is still decremented.
            // So the invariant: contractBalanceAfter = contractBalanceBefore - am (reference holds, mutant breaks)
            assertTrue(contractBalanceAfter == contractBalanceBefore - am, "Contract balance should decrease by am");
            // Also the sender's balance increase (minus gas) is not reliable due to gas costs. So stick to contract balance.
        } else {
            // If Collect reverts, no state change in either version (both revert on failed send? Actually if send fails, both revert entirely, so no diff)
            assertTrue(true);
        }
    }
}

