pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 unlockTime, uint256 initialBalance, uint256 minSum, uint256 am) public {
        // Bound inputs to reasonable ranges
        vm.assume(caller != address(0));
        am = bound(am, 0, 1e18);
        initialBalance = bound(initialBalance, am, 1e18);
        minSum = bound(minSum, 0, initialBalance);
        unlockTime = bound(unlockTime, 0, 1000);

        // Setup: deploy, set minSum, initialize, fund contract
        c.SetMinSum(minSum);
        c.Initialized();
        vm.deal(address(c), initialBalance);

        // Setup caller's account in contract with initialBalance
        vm.prank(caller);
        c.Put{value: 0}(0); // caller deposits 0 to create account entry
        // but we need to set their balance to initialBalance manually; we can't, so we'll use a different approach
        // Actually we need to simulate direct balance. Since we can't set Acc[caller].balance directly,
        // we'll put the balance by sending ETH
        vm.prank(caller);
        c.Put{value: initialBalance}(unlockTime);

        uint256 callerEthBefore = caller.balance;
        uint256 cEthBefore = address(c).balance;

        // Perform Collect attempt
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, am));

        uint256 callerEthAfter = caller.balance;
        uint256 cEthAfter = address(c).balance;

        // The rule: if Collect succeeds, caller gained exactly am ETH, and contract lost exactly am ETH
        if (success) {
            assertTrue(callerEthAfter - callerEthBefore == am, "Caller should receive exactly am");
            assertTrue(cEthBefore - cEthAfter == am, "Contract should lose exactly am");
        } else {
            // If it reverts, no ETH should have moved
            assertTrue(callerEthAfter == callerEthBefore, "No ETH transfer on revert");
            assertTrue(cEthAfter == cEthBefore, "No ETH transfer on revert");
        }
    }
}

